using System.Diagnostics; namespace NXT.Core; public static class AdbManager {public static async Task InstallAsync(string adb,string apk){if(!File.Exists(adb))throw new FileNotFoundException("ADB not bundled; add platform-tools under runtime/platform-tools.");var p=new ProcessStartInfo(adb){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true};foreach(var a in new[]{"-s","127.0.0.1:5555","install","-r",apk})p.ArgumentList.Add(a);using var process=Process.Start(p)??throw new InvalidOperationException("ADB failed to start");string error=await process.StandardError.ReadToEndAsync();await process.WaitForExitAsync();if(process.ExitCode!=0)throw new Exception(error);}}